Test.Text:
create procedure CK.sTest as
begin
  insert into S.tTable default values;
  insert into S.tOther default values;
end

Test.Description:
create transformer on CK.sTest as
begin
  inject " set @X = 0; " before all part {insert into S.?};
  inject [ set @Table = 1; ] before single part {insert into S.tTable};
end

Test.ResultText:
create procedure CK.sTest as
begin
  set @Table = 1; set @X = 0; insert into S.tTable default values;
  set @X = 0; insert into S.tOther default values;
end

Test.Description:
create transformer on CK.sTest as
begin
  inject ' order by Name' after single part {select top 1 Name};
  inject ', 2 /* after order! */'  after single part {select top 20};
  inject 'X; /* after statement! */'  after single statement {select A};
end
